import React from 'react';
import { Link } from 'react-router-dom';

export default function Home() {
  return (
    <div>
      <div className="relative bg-neutral-900 h-[650px] flex items-center justify-center text-white overflow-hidden">
        <div className="absolute inset-0 bg-cover bg-center opacity-40" style={{ backgroundImage: `url('http://localhost:5000/public/uploads/hero-car.jpg')` }}></div>
        <div className="relative z-10 text-center max-w-4xl px-6">
          <h1 className="text-6xl font-black mb-6 uppercase tracking-tight">Quick and affordable<br/><span className="text-yellow-400">car rentals</span></h1>
          <p className="text-xl text-gray-300 mb-8 max-w-2xl mx-auto">Streamlined urban transit and cross-country execution engine. Secure execution, instant access.</p>
          <Link to="/cars" className="bg-yellow-400 text-neutral-950 font-bold px-8 py-4 rounded shadow-lg text-lg hover:bg-yellow-500 transition">
            View Rental Collection →
          </Link>
        </div>
      </div>
    </div>
  );
}
